    float foldingLimit;
    float glowIntensity;
    float colorMix;
    int fractalIterations;
    int colorIterations;
    int maxRaySteps;
    float maxViewDistance;
    // Infinite zoom: 1/max(effectiveScale,1). Scales the raymarch hit-threshold
