"""#

    static let mandelbulbH: String = #"""
//
//  Mandelbulb.h
//  Threshold
//
//  Distance estimator for the Mandelbulb fractal.
//  params[0]=Power, [1]=Bailout, [2]=DerivBias (DE multiplier for resolution),
//  [4]=PolarRotation, [8]=Julia(bool), [9-11]=JuliaC
//
//  Requires: FractalFormulaCommon.h
//

#ifndef DE_Mandelbulb_h
#define DE_Mandelbulb_h

// When FC_MANDELBULB_POWER is baked via function constants, the compiler
// constant-folds all power multiplications and dead-code-eliminates unused
// branches in fastPowR — giving compile-time-optimized code for each integer power.
#ifdef __METAL_VERSION__
  // Declared in Shaders.metal; available to all included headers.
  // is_function_constant_defined checks at compile time.
  #define MB_POWER_CONST (is_function_constant_defined(FC_MANDELBULB_POWER) ? float(FC_MANDELBULB_POWER) : fp.params[0])
#else
  #define MB_POWER_CONST fp.params[0]
#endif

FORCE_INLINE float DE_Mandelbulb(float3 pos, FormulaParams fp, float3x3 rot,
                                 int iterations, int colorIterations,
                                 thread OrbitData& orbit) {
    float power   = MB_POWER_CONST;
    float bailout = fp.params[1];
    float dBias   = max(fp.params[2], 0.01f);  // Clamp minimum for safety
    float polarRot  = fp.params[4];
    bool  julia     = fp.params[8] > 0.5f;
    float3 juliaC   = float3(fp.params[9], fp.params[10], fp.params[11]);
    // CPU precomputes identity flag — skip the 3x3 matmul when rotation is identity.
    bool applyRot = hasRot1Precomputed(fp);

    float3 z = pos;
    float3 c = julia ? juliaC : pos;
    float dr = 1.0f;
    float r2 = dot(z, z);

    float trap = 1e20f;
    int trapIter = 0;
    float3 trapPos = z;
    int i = 0;

    // Precompute bailout² once outside the loop.
    float bailout2 = bailout * bailout;
    // Min-distance early exit: once r is tiny we're on/inside the surface.
    // Skipping remaining trig-heavy iterations saves significant ALU at deep zoom.
    const float minR2Exit = 1e-12f;

    for (; i < iterations && r2 < bailout2 && r2 > minR2Exit; ) {
        float invR  = fast::rsqrt(r2 + 1e-6f); // shared 1/r (avoids div-by-zero)

        float theta = fast::asin(clamp11(z.z * invR)) + polarRot;
        float phi   = fast::atan2(z.y, z.x);
        float rn    = fastPowFromR2(r2, power);
        dr = fma(rn * power * invR, dr, 1.0f);

        float tP = theta * power, pP = phi * power;
        float cTheta, cPhi;
        float sTheta = sincos(tP, cTheta);
        float sPhi   = sincos(pP, cPhi);

        z = rn * float3(cTheta * cPhi,
                        cTheta * sPhi,
                        sTheta);

        z += c;
        if (applyRot) z = rot * z;

        r2 = dot(z, z);

        UpdateTrapMinR2(trap, trapIter, trapPos, r2, i, colorIterations, z);
        ++i;
    }

    orbit.trap = trap;
    orbit.trapIteration = trapIter;
    orbit.trapPosition = trapPos;
    orbit.finalP = z;
    orbit.iterationsUsed = i;

    // dBias acts as a DE multiplier: <1 = finer surface detail, >1 = coarser/faster.
    // The additive bias in the loop is fixed at 1.0 for numerical stability;
    // dBias scales the final result for user-controllable resolution.
    float r = fast::sqrt(r2);
    float safeR = max(r, 1e-6f);  // Prevent log2(~0) → -∞
    float de = dBias * 0.5f * safeR * fast::log2(safeR) / max(dr, kEpsLen) * kLn2;
    // Cap far-field step to distance-to-inner-bailout-sphere.
    // Using 90% of bailout keeps a minimum cap of bailout*0.1 at the boundary,
    // preventing the false surface that `r - bailout → 0` would create.
    // Thin Julia features near the boundary are preserved because when a surface
    // IS nearby, the computed DE is already smaller than the cap (min is a no-op).
    if (r > bailout) {
        de = min(de, r - bailout * 0.9f);
    }
    return de;
}

// Lean distance-only: no orbit tracking, no struct writes.
FORCE_INLINE float DE_Mandelbulb_Dist(float3 pos, FormulaParams fp, float3x3 rot, int iterations) {
    float power   = MB_POWER_CONST;
    float bailout = fp.params[1];
    float bailout2 = bailout * bailout;
    float dBias   = max(fp.params[2], 0.01f);  // Clamp minimum for safety
    float polarRot  = fp.params[4];
    bool  julia     = fp.params[8] > 0.5f;
    float3 juliaC   = float3(fp.params[9], fp.params[10], fp.params[11]);
    bool applyRot = hasRot1Precomputed(fp);

    float3 z = pos;
    float3 c = julia ? juliaC : pos;
    float dr = 1.0f;
    float r2 = dot(z, z);

    // Min-distance early exit: once r is tiny we're on/inside the surface.
    const float minR2Exit = 1e-12f;

    for (int i = 0; i < iterations && r2 < bailout2 && r2 > minR2Exit; ++i) {
        float invR  = fast::rsqrt(r2 + 1e-6f);
        float theta = fast::asin(clamp11(z.z * invR)) + polarRot;
        float phi   = fast::atan2(z.y, z.x);
        float rn    = fastPowFromR2(r2, power);
        dr = fma(rn * power * invR, dr, 1.0f);
        float tP = theta * power, pP = phi * power;
        float cTheta, cPhi;
        float sTheta = sincos(tP, cTheta);
        float sPhi   = sincos(pP, cPhi);
        z = rn * float3(cTheta * cPhi,
                        cTheta * sPhi,
                        sTheta);
        z += c;
        if (applyRot) z = rot * z;
        r2 = dot(z, z);
    }

    float r = fast::sqrt(r2);
    float safeR = max(r, 1e-6f);  // Prevent log2(~0) → -∞
    float de = dBias * 0.5f * safeR * fast::log2(safeR) / max(dr, kEpsLen) * kLn2;
    // Cap far-field step to distance-to-inner-bailout-sphere (see full DE above).
    if (r > bailout) {
        de = min(de, r - bailout * 0.9f);
    }
    return de;
}

#endif /* DE_Mandelbulb_h */

"""#

    static let mengerH: String = #"""
//
//  Menger.h
//  Threshold
//
//  Distance estimator for the Menger Sponge fractal.
//  params[0]=Scale, [1-3]=Offset
//
//  Requires: FractalFormulaCommon.h
//

#ifndef DE_Menger_h
#define DE_Menger_h

FORCE_INLINE float DE_Menger(float3 pos, FormulaParams fp, float3x3 rot,
                             int iterations, int colorIterations,
                            thread OrbitData& orbit) {
    float scale  = fp.params[0];
    float3 offset = float3(fp.params[1], fp.params[2], fp.params[3]);

    float3 z = pos;
    float dr = 1.0f;
    float trap = 1e20f;
    int trapIter = 0;
    float3 trapPos = z;
    int i = 0;

    for (; i < iterations; ++i) {
        // Fold into positive octant
        z = abs(z);
        // Sort components so z.x >= z.y >= z.z
        float sum = z.x + z.y + z.z;
        float min_xy = min(z.x, z.y);
        float max_xy = max(z.x, z.y);
        float min_z = min(min_xy, z.z);
        float max_z = max(max_xy, z.z);
        z.x = max_z;
        z.z = min_z;
        z.y = sum - (max_z + min_z);

        float3 offsetScaled = offset * (scale - 1.0f);
        z = z * scale - offsetScaled;
        
        float foldZ = -0.5f * offsetScaled.z;
        z.z += (z.z < foldZ) ? offsetScaled.z : 0.0f;

        z = rot * z;
        dr = dr * abs(scale) + 1.0f;

        float r2 = dot(z, z);
        UpdateTrapMinR2(trap, trapIter, trapPos, r2, i, colorIterations, z);
    }

    orbit.trap = trap;
    orbit.trapIteration = trapIter;
    orbit.trapPosition = trapPos;
    orbit.finalP = z;
    orbit.iterationsUsed = i;

    float r = fast::length(z);
    return (r - 1.0f) / dr;
}

// Lean distance-only: no orbit tracking, no struct writes.
FORCE_INLINE float DE_Menger_Dist(float3 pos, FormulaParams fp, float3x3 rot, int iterations) {
    float scale  = fp.params[0];
    float3 offset = float3(fp.params[1], fp.params[2], fp.params[3]);
    float3 offsetScaled = offset * (scale - 1.0f);
    float halfOffsetZn = -0.5f * offsetScaled.z;

    float3 z = pos;
    float dr = 1.0f;

    for (int i = 0; i < iterations; ++i) {
        z = abs(z);
        float sum = z.x + z.y + z.z;
        float min_xy = min(z.x, z.y);
        float max_xy = max(z.x, z.y);
        float min_z = min(min_xy, z.z);
        float max_z = max(max_xy, z.z);
        z.x = max_z;
        z.z = min_z;
        z.y = sum - (max_z + min_z);

        z = z * scale - offsetScaled;
        z.z += (z.z < halfOffsetZn) ? offsetScaled.z : 0.0f;

        z = rot * z;
        dr = dr * abs(scale) + 1.0f;
    }

    return (fast::length(z) - 1.0f) / dr;
}

#endif /* DE_Menger_h */

"""#

    static let quaternionJuliaH: String = #"""
//
//  QuaternionJulia.h
//  Threshold
//
//  Distance estimator for the Quaternion Julia set fractal.
//  params[0-3]=C(x,y,z,w), [4]=Threshold
//
//  Requires: FractalFormulaCommon.h
//

#ifndef DE_QuaternionJulia_h
#define DE_QuaternionJulia_h

FORCE_INLINE float DE_QuaternionJulia(float3 pos, FormulaParams fp, float3x3 rot,
                                      int iterations, int colorIterations,
                                     thread OrbitData& orbit) {
    float4 c = float4(fp.params[0], fp.params[1], fp.params[2], fp.params[3]);
    float threshold = fp.params[4];

    // q = quaternion (x,y,z,w), start at (pos, 0)
    float4 q = float4(pos, 0.0f);
    float4 dq = float4(1.0f, 0.0f, 0.0f, 0.0f);
    float trap = 1e20f;
    int trapIter = 0;
    float3 trapPos = pos;
    int i = 0;

    for (; i < iterations; ++i) {
        // dq = 2 * q * dq (quaternion multiplication for derivative)
        dq = 2.0f * float4(
            q.x*dq.x - q.y*dq.y - q.z*dq.z - q.w*dq.w,
            q.x*dq.y + q.y*dq.x + q.z*dq.w - q.w*dq.z,
            q.x*dq.z - q.y*dq.w + q.z*dq.x + q.w*dq.y,
            q.x*dq.w + q.y*dq.z - q.z*dq.y + q.w*dq.x
        );

        // q = q*q + c (quaternion squaring)
        q = float4(
            q.x*q.x - q.y*q.y - q.z*q.z - q.w*q.w,
            2.0f*q.x*q.y,
            2.0f*q.x*q.z,
            2.0f*q.x*q.w
        ) + c;

        float r2 = dot(q, q);
        UpdateTrapMinR2(trap, trapIter, trapPos, r2, i, colorIterations, q.xyz);

        if (r2 > threshold) break;
    }

    orbit.trap = trap;
    orbit.trapIteration = trapIter;
    orbit.trapPosition = trapPos;
    orbit.finalP = q.xyz;
    orbit.iterationsUsed = i;

    float r = fast::length(q);
    float dr = fast::length(dq);
    float safeR = max(r, 1e-6f);  // Prevent log(~0) → -∞
    return 0.5f * safeR * fast::log(safeR) / max(dr, kEpsLen);
}

// Lean distance-only: no orbit tracking, no struct writes.
FORCE_INLINE float DE_QuaternionJulia_Dist(float3 pos, FormulaParams fp, float3x3 rot, int iterations) {
    float4 c = float4(fp.params[0], fp.params[1], fp.params[2], fp.params[3]);
    float threshold = fp.params[4];

    float4 q = float4(pos, 0.0f);
    float4 dq = float4(1.0f, 0.0f, 0.0f, 0.0f);

    for (int i = 0; i < iterations; ++i) {
        dq = 2.0f * float4(
            q.x*dq.x - q.y*dq.y - q.z*dq.z - q.w*dq.w,
            q.x*dq.y + q.y*dq.x + q.z*dq.w - q.w*dq.z,
            q.x*dq.z - q.y*dq.w + q.z*dq.x + q.w*dq.y,
            q.x*dq.w + q.y*dq.z - q.z*dq.y + q.w*dq.x
        );

        q = float4(
            q.x*q.x - q.y*q.y - q.z*q.z - q.w*q.w,
            2.0f*q.x*q.y,
            2.0f*q.x*q.z,
            2.0f*q.x*q.w
        ) + c;

        if (dot(q, q) > threshold) break;
    }

    float r = fast::length(q);
    float safeR = max(r, 1e-6f);  // Prevent log(~0) → -∞
    return 0.5f * safeR * fast::log(safeR) / max(fast::length(dq), kEpsLen);
}

#endif /* DE_QuaternionJulia_h */

"""#

    static let octahedronH: String = #"""
//
//  Octahedron.h
//  Threshold
//
//  Distance estimator for the Octahedron IFS fractal.
//  params[0]=Scale, [1-3]=Offset
//
//  Requires: FractalFormulaCommon.h
//

#ifndef DE_Octahedron_h
#define DE_Octahedron_h

FORCE_INLINE float DE_Octahedron(float3 pos, FormulaParams fp, float3x3 rot,
                                 int iterations, int colorIterations,
                                thread OrbitData& orbit) {
    float scale  = fp.params[0];
    float3 offset = float3(fp.params[1], fp.params[2], fp.params[3]);

    float3 z = pos;
    float dr = 1.0f;
    float trap = 1e20f;
    int trapIter = 0;
    float3 trapPos = z;
    int i = 0;

    for (; i < iterations; ++i) {
        // Octahedral folds (abs + sort = octahedral symmetry)
        z = abs(z);
        if (z.x - z.y < 0.0f) z.xy = z.yx;
        if (z.x - z.z < 0.0f) z.xz = z.zx;
        if (z.y - z.z < 0.0f) z.yz = z.zy;

        z = z * scale - offset * (scale - 1.0f);
        z = rot * z;
        dr = dr * scale + 1.0f;

        float r2 = dot(z, z);
        UpdateTrapMinR2(trap, trapIter, trapPos, r2, i, colorIterations, z);
    }

    orbit.trap = trap;
    orbit.trapIteration = trapIter;
    orbit.trapPosition = trapPos;
    orbit.finalP = z;
    orbit.iterationsUsed = i;

    float r = fast::length(z);
    return (r - 1.0f) / dr;
}

// Lean distance-only: no orbit tracking, no struct writes.
FORCE_INLINE float DE_Octahedron_Dist(float3 pos, FormulaParams fp, float3x3 rot, int iterations) {
    float scale  = fp.params[0];
    float3 offset = float3(fp.params[1], fp.params[2], fp.params[3]);
    float3 offsetScaled = offset * (scale - 1.0f);

    float3 z = pos;
    float dr = 1.0f;

    for (int i = 0; i < iterations; ++i) {
        z = abs(z);
        if (z.x - z.y < 0.0f) z.xy = z.yx;
        if (z.x - z.z < 0.0f) z.xz = z.zx;
        if (z.y - z.z < 0.0f) z.yz = z.zy;

        z = z * scale - offsetScaled;
        z = rot * z;
        dr = dr * scale + 1.0f;
    }

    return (fast::length(z) - 1.0f) / dr;
}

