    float scale = 1.0f;

    float trap = 1e20f;
    int trapIter = 0;
    float3 trapPos = pos;
    int trapIterations = min(max(colorIterations, 0), iterations);

    int i = 0;
    if (hasRotation) {
        for (; i < iterations; ++i) {
            p = rot * p;

            // Box fold: 2 * clamp(p, mins, maxs) - p
            p = fma(clamp(p, mins, maxs), float3(2.0f), -p);

            // Sphere fold
            float r2 = dot(p, p);
            float k = max(sphFold / max(r2, 1e-6f), 1.0f);
            p *= k;
            scale *= k;

