                float r2Trap = dot(p, p);
                if (r2Trap < trap) {
                    trap = r2Trap;
                    trapIter = i;
                    trapPos = p;
                }
            }
        }
    } else {
        for (; i < iterations; ++i) {
            p = fma(clamp(p, mins, maxs), float3(2.0f), -p);

            float r2 = dot(p, p);
            float k = max(sphFold / max(r2, 1e-6f), 1.0f);
            p *= k;
            scale *= k;

